SELECT table_name||' :: '||column_name||' :: '||data_type||CASE WHEN character_maximum_length IS NOT NULL THEN '('||character_maximum_length||')' ELSE CASE WHEN numeric_precision IS NOT NULL THEN '('||numeric_precision||','||COALESCE(numeric_scale,0)||')' ELSE '' END END||CASE WHEN is_nullable='NO' THEN ' NN' ELSE '' END FROM information_schema.columns WHERE table_schema='public' AND table_name IN ('transactions','cards','user_cards','ledger_entries','crypto_wallets','merchant_profiles','momo_gateway_mappings','bill_payments','remittances','fraud_alerts') ORDER BY table_name, ordinal_position;
